<?php
require_once dirname(__DIR__,2).'/src/media.php';require_method('GET');$u=current_user();$q=db()->prepare("SELECT s.* FROM stories s WHERE s.deleted_at IS NULL AND s.expires_at>UTC_TIMESTAMP(6) AND (s.owner_id=? OR (s.audience='close_friends' AND EXISTS(SELECT 1 FROM close_friends c WHERE c.owner_id=s.owner_id AND c.member_id=?)) OR (s.audience='public' AND EXISTS(SELECT 1 FROM friendships f WHERE (f.user_low=s.owner_id AND f.user_high=?) OR (f.user_high=s.owner_id AND f.user_low=?)))) ORDER BY s.created_at,s.id LIMIT 200");$q->execute([$u['id'],$u['id'],$u['id'],$u['id']]);json_response(['stories'=>$q->fetchAll(),'server_time'=>gmdate(DATE_ATOM)]);
